(function(){
'use strict';
var VERSION='2.2.7';
var moneyFmt=new Intl.NumberFormat('en-GB',{style:'currency',currency:'GBP'});
var wizardDraft=[];
var profileDrafts=new Map();
var indexCache=null,indexSignature='';
var renderQueued=false;

function products(){
  try{
    if(typeof window.__POOL_SHED_GET_PRODUCTS__==='function'){
      var bridged=window.__POOL_SHED_GET_PRODUCTS__();
      if(Array.isArray(bridged))return bridged;
    }
  }catch(_){}
  try{
    if(typeof window.__POOL_SHED_GET_DATA__==='function'){
      var appData=window.__POOL_SHED_GET_DATA__();
      if(appData&&Array.isArray(appData.products))return appData.products;
    }
  }catch(_){}
  try{if(typeof data!=='undefined'&&data&&Array.isArray(data.products))return data.products}catch(_){}
  return window.data&&Array.isArray(window.data.products)?window.data.products:[]
}
function productById(id){return typeof window.product==='function'?window.product(id):products().find(function(p){return String(p.id)===String(id)})}
function esc(v){return String(v==null?'':v).replace(/[&<>"']/g,function(c){return({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'})[c]})}
function money(v){return moneyFmt.format(Number(v||0))}
function stock(p){try{var fn=window.__poolShedOriginalProductStockSummary||window.productStockSummary;return fn?fn(p.id):{onHand:Number(p.stock||0),allocated:0,available:Number(p.stock||0)}}catch(_){return{onHand:Number(p.stock||0),allocated:0,available:Number(p.stock||0)}}}
function isBundle(p){var t=String((p&&p.productType)||(p&&p.structure)||'').toLowerCase();return t==='bundle'||t==='bundle product'}
function linked(p){return Array.isArray(p&&p.bundleItems)?p.bundleItems.filter(function(x){return x&&x.productId&&Number(x.qty)>0}).map(function(x){return{productId:x.productId,qty:Number(x.qty||1),displayOrder:Number(x.displayOrder||0)}}):[]}
function cloneItems(items){return JSON.parse(JSON.stringify(items||[]))}
function profileDraft(p){var key=String(p.id);if(!profileDrafts.has(key))profileDrafts.set(key,cloneItems(linked(p)));return profileDrafts.get(key)}
function image(p){var src=(p&&(p.imageUrl||p.parentImageUrl))||'';return src?'<img loading="lazy" src="'+esc(src)+'" alt="">':'<span class="bs-thumb-fallback">PS</span>'}
function normaliseText(v){return String(v||'').toLowerCase().replace(/[^a-z0-9]+/g,' ').trim()}
function productSearchText(p){return normaliseText([
  p.name,p.productName,p.title,p.sku,p.productSku,p.code,p.productCode,
  p.barcode,p.ean,p.upc,p.supplierSku,p.supplierSKU,p.vendorSku,p.manufacturerSku,
  p.brand,p.category,p.supplier,p.parentName,p.variantName,p.variantValue
].join(' '))}
function catalogueSignature(list){var first=list[0]||{},last=list[list.length-1]||{};return [list.length,first.id,first.sku,last.id,last.sku].join('|')}
function searchIndex(){var list=products(),sig=catalogueSignature(list);if(indexCache&&indexSignature===sig)return indexCache;indexSignature=sig;indexCache=list.filter(function(p){return p&&!p.deleted&&!p.hiddenFromCatalogue}).map(function(p){return{p:p,text:productSearchText(p),sku:normaliseText(p.sku||p.productSku||p.code||p.productCode)}});return indexCache}
function searchProducts(query,excludeId,existing){var q=normaliseText(query);if(q.length<2)return[];var terms=q.split(/\s+/),set=new Set((existing||[]).map(String));return searchIndex().filter(function(row){var p=row.p;if(String(p.id)===String(excludeId)||set.has(String(p.id)))return false;return terms.every(function(t){return row.text.indexOf(t)>=0})}).sort(function(a,b){var ae=a.sku===q?0:a.sku.indexOf(q)===0?1:a.text.indexOf(q)===0?2:3;var be=b.sku===q?0:b.sku.indexOf(q)===0?1:b.text.indexOf(q)===0?2:3;return ae-be}).slice(0,10).map(function(r){return r.p})}
function calc(items){var cost=0,rrp=0,weight=0,available=Infinity,limiter=null,warnings=[];items.forEach(function(row){var p=productById(row.productId);if(!p)return;var q=Math.max(1,Number(row.qty||1));var s=isBundle(p)&&window.PoolShedBundleSystem?window.PoolShedBundleSystem.calculate(p):stock(p);var unitCost=isBundle(p)&&s.cost!=null?Number(s.cost):Number(p.cost||0);var unitRrp=isBundle(p)&&s.sell!=null?Number(s.sell):Number(p.rrp||0);var av=Math.floor(Number(s.available||0)/q);cost+=unitCost*q;rrp+=unitRrp*q;weight+=Number(p.weight||0)*q;if(av<available){available=av;limiter=p}if(String(p.status||'Live').toLowerCase().match(/archived|discontinued/))warnings.push((p.sku||p.name)+' is not active.');});if(!items.length)available=0;return{cost:cost,rrp:rrp,weight:weight,available:available===Infinity?0:available,limiter:limiter,warnings:warnings}}
function statusFor(av,need){if(av<=0)return['red','Out of stock'];if(av<need)return['amber','Short stock'];return['green','Ready']}
function resultRow(p){var s=isBundle(p)&&window.PoolShedBundleSystem?window.PoolShedBundleSystem.calculate(p):stock(p);var av=Number(s.available||0),st=statusFor(av,1);return '<button type="button" class="bs-result" data-bs-add="'+esc(p.id)+'">'+image(p)+'<span class="bs-result-copy"><strong>'+esc(p.name||'Unnamed product')+'</strong><em>'+esc(p.sku||'No SKU')+(p.barcode?' · '+esc(p.barcode):'')+'</em><small>'+esc(p.brand||p.supplier||'Catalogue product')+'</small></span><span class="bs-result-stock '+st[0]+'"><b>'+av+'</b><small>available</small></span><span class="bs-result-price"><b>'+money(isBundle(p)&&s.sell!=null?s.sell:p.rrp)+'</b><small>RRP</small></span><span class="bs-result-add">Add</span></button>'}
function componentRow(row){var p=productById(row.productId);if(!p)return'';var s=isBundle(p)&&window.PoolShedBundleSystem?window.PoolShedBundleSystem.calculate(p):stock(p);var av=Number(s.available||0),q=Math.max(1,Number(row.qty||1)),st=statusFor(av,q);var unitCost=isBundle(p)&&s.cost!=null?s.cost:p.cost,unitRrp=isBundle(p)&&s.sell!=null?s.sell:p.rrp;return '<article class="bs-component" data-bs-component="'+esc(p.id)+'"><div class="bs-component-head"><div class="bs-product-cell">'+image(p)+'<div><strong>'+esc(p.name||'Unnamed product')+'</strong><span>'+esc(p.sku||'No SKU')+(isBundle(p)?' · Nested bundle':'')+'</span></div></div><div class="bs-component-actions"><button type="button" data-bs-open="'+esc(p.id)+'">View product</button><button type="button" class="danger" data-bs-remove="'+esc(p.id)+'" aria-label="Remove component">Remove</button></div></div><div class="bs-component-metrics"><label><span>Quantity</span><input type="number" min="1" step="1" value="'+q+'" data-bs-qty="'+esc(p.id)+'"></label><div><span>Available stock</span><strong class="bs-pill '+st[0]+'">'+av+' · '+st[1]+'</strong></div><div><span>Component cost</span><strong>'+money(Number(unitCost||0)*q)+'</strong></div><div><span>Component RRP</span><strong>'+money(Number(unitRrp||0)*q)+'</strong></div><div><span>Catalogue link</span><strong class="bs-linked-badge">Linked</strong></div></div></article>'}
function summary(items,sellingPrice){var c=calc(items),sell=Number(sellingPrice||0),profit=sell-c.cost,margin=sell>0?profit/sell*100:0,saving=Math.max(0,c.rrp-sell);return '<aside class="bs-summary"><div class="bs-summary-status '+(c.available>0?'green':'red')+'"><span>Effective bundle stock</span><strong>'+c.available+'</strong><em>'+(c.limiter?'Limited by '+esc(c.limiter.name):'Add components to calculate')+'</em></div><div class="bs-summary-grid"><div><span>Component cost</span><strong>'+money(c.cost)+'</strong></div><div><span>Component RRP</span><strong>'+money(c.rrp)+'</strong></div><div><span>Bundle price</span><strong>'+money(sell)+'</strong></div><div><span>Customer saving</span><strong>'+money(saving)+'</strong></div><div><span>Gross profit</span><strong>'+money(profit)+'</strong></div><div><span>Gross margin</span><strong>'+margin.toFixed(1)+'%</strong></div><div><span>Total weight</span><strong>'+c.weight.toFixed(2)+' kg</strong></div><div><span>Linked products</span><strong>'+items.length+'</strong></div></div>'+(c.warnings.length?'<div class="bs-alert"><strong>Needs attention</strong>'+c.warnings.map(function(w){return'<p>'+esc(w)+'</p>'}).join('')+'</div>':'<div class="bs-ok">Catalogue links and stock calculation are healthy.</div>')+'</aside>'}
function builderShell(opts){var items=opts.items||[],price=Number(opts.price||0);return '<div class="bs-studio" data-bs-mode="'+opts.mode+'"'+(opts.productId?' data-bs-product-id="'+esc(opts.productId)+'"':'')+'><header class="bs-hero"><div><span>POOL SHED · SMART BUNDLE BUILDER</span><h2>Build from your live product catalogue</h2><p>Search and link existing SKUs. Product details, costs, supplier information and stock remain connected to the original catalogue record.</p></div><div class="bs-hero-badges"><span>Virtual product</span><span>No duplicate stock</span><span>Live availability</span></div></header><div class="bs-layout"><main><section class="bs-card bs-search-card"><div class="bs-section-title"><div><span class="bs-step">01</span><div><h3>Add catalogue products</h3><p>Open the full catalogue selector to search, compare and add multiple products at once.</p></div></div><span class="bs-count">'+items.length+' linked</span></div><button type="button" class="bs-open-picker" data-bs-open-picker><span class="bs-open-picker-icon">⌕</span><span><strong>Open catalogue selector</strong><small>Search by product name, SKU, supplier SKU, barcode, brand or category</small></span><em>Browse products</em></button><div class="bs-search-help"><span>Bulk selection</span><span>Exact SKU matching</span><span>Stock and pricing shown</span><span>Links original catalogue records</span></div></section><section class="bs-card"><div class="bs-section-title"><div><span class="bs-step">02</span><div><h3>Bundle components</h3><p>Every row is linked to the existing Product Hub record.</p></div></div><button type="button" class="bs-add-more" data-bs-open-picker>+ Add products</button></div><div class="bs-components" data-bs-components>'+(items.length?items.map(componentRow).join(''):'<div class="bs-empty"><span>+</span><strong>No products linked yet</strong><p>Open the catalogue selector to add the first component.</p><button type="button" data-bs-open-picker>Browse catalogue</button></div>')+'</div></section></main>'+summary(items,price)+'</div><div class="bs-footnote"><strong>Stock rule:</strong> availability is calculated from the lowest number of complete bundles possible across every linked component.</div></div>'}

var pickerState={root:null,selected:new Set(),query:'',page:0};
function pickerProductRow(p){var st=stock(p),av=Number(st.available||0),state=statusFor(av,1),checked=pickerState.selected.has(String(p.id));return '<label class="bs-picker-row'+(checked?' selected':'')+'"><input type="checkbox" data-bs-picker-select="'+esc(p.id)+'"'+(checked?' checked':'')+'><span class="bs-picker-check"></span>'+image(p)+'<span class="bs-picker-product"><strong>'+esc(p.name||'Unnamed product')+'</strong><em>'+esc(p.sku||'No SKU')+(p.barcode?' · '+esc(p.barcode):'')+'</em><small>'+esc(p.brand||p.supplier||'Catalogue product')+'</small></span><span class="bs-picker-stock '+state[0]+'"><b>'+av+'</b><small>available</small></span><span class="bs-picker-money"><b>'+money(p.cost||0)+'</b><small>Cost</small></span><span class="bs-picker-money"><b>'+money(p.rrp||0)+'</b><small>RRP</small></span></label>'}
function pickerMatches(){var root=pickerState.root,items=root?stateFrom(root):[],q=normaliseText(pickerState.query),existing=new Set(items.map(function(x){return String(x.productId)}));var list=searchIndex().filter(function(row){var p=row.p;if(String(p.id)===String(root&&root.dataset.bsProductId)||existing.has(String(p.id)))return false;if(!q)return true;return q.split(/\s+/).every(function(t){return row.text.indexOf(t)>=0})}).sort(function(a,b){if(!q)return String(a.p.name||'').localeCompare(String(b.p.name||''));var ae=a.sku===q?0:a.sku.indexOf(q)===0?1:a.text.indexOf(q)===0?2:3,be=b.sku===q?0:b.sku.indexOf(q)===0?1:b.text.indexOf(q)===0?2:3;return ae-be||String(a.p.name||'').localeCompare(String(b.p.name||''))});return list.map(function(x){return x.p})}
function renderPicker(){var modal=document.querySelector('[data-bs-picker-modal]');if(!modal)return;var all=pickerMatches(),limit=60,shown=all.slice(0,limit),list=modal.querySelector('[data-bs-picker-list]'),count=modal.querySelector('[data-bs-picker-count]'),selected=modal.querySelector('[data-bs-picker-selected-count]'),add=modal.querySelector('[data-bs-picker-add]');list.innerHTML=shown.length?shown.map(pickerProductRow).join(''):'<div class="bs-picker-empty"><strong>No matching products</strong><span>Try a shorter SKU, product name, supplier, brand or barcode.</span></div>';count.textContent=all.length+' product'+(all.length===1?'':'s');selected.textContent=pickerState.selected.size+' selected';add.disabled=pickerState.selected.size===0;add.textContent=pickerState.selected.size?'Add '+pickerState.selected.size+' selected':'Add selected products'}
function openPicker(root){pickerState.root=root;pickerState.selected=new Set();pickerState.query='';var old=document.querySelector('[data-bs-picker-modal]');if(old)old.remove();var modal=document.createElement('div');modal.className='bs-picker-overlay';modal.dataset.bsPickerModal='';modal.innerHTML='<div class="bs-picker-modal" role="dialog" aria-modal="true" aria-label="Select bundle products"><header><div><span>POOL SHED PRODUCT HUB</span><h2>Add products to bundle</h2><p>Select one or multiple existing catalogue products. No duplicate products or stock records are created.</p></div><button type="button" class="bs-picker-close" data-bs-picker-close aria-label="Close">×</button></header><div class="bs-picker-toolbar"><div class="bs-picker-search"><span>⌕</span><input type="search" data-bs-picker-search autocomplete="off" placeholder="Search product name, SKU, supplier SKU, barcode, brand or category"></div><div class="bs-picker-meta"><strong data-bs-picker-count>0 products</strong><span data-bs-picker-selected-count>0 selected</span></div></div><div class="bs-picker-columns"><span></span><span></span><span>Product</span><span>Stock</span><span>Cost</span><span>RRP</span></div><div class="bs-picker-list" data-bs-picker-list></div><footer><div><strong>Selected products stay linked to Product Hub</strong><span>Stock, cost, supplier and product details remain live.</span></div><button type="button" class="secondary" data-bs-picker-clear>Clear selection</button><button type="button" data-bs-picker-add disabled>Add selected products</button></footer></div>';document.body.appendChild(modal);document.body.classList.add('bs-picker-open');renderPicker();setTimeout(function(){var input=modal.querySelector('[data-bs-picker-search]');if(input)input.focus()},0)}
function closePicker(){var modal=document.querySelector('[data-bs-picker-modal]');if(modal)modal.remove();document.body.classList.remove('bs-picker-open');pickerState.root=null;pickerState.selected=new Set();pickerState.query=''}
function addPickerSelection(){var root=pickerState.root;if(!root||!pickerState.selected.size)return;var items=stateFrom(root),next=items.slice();pickerState.selected.forEach(function(id){if(!next.some(function(x){return String(x.productId)===String(id)}))next.push({productId:id,qty:1,displayOrder:next.length})});if(root.dataset.bsMode==='wizard')wizardDraft=next;else{var p=productById(root.dataset.bsProductId);if(p)profileDrafts.set(String(p.id),next)}closePicker();rerender(root)}

function profileBuilder(p){return builderShell({mode:'profile',productId:p.id,items:profileDraft(p),price:Number(p.bundleManualRrp||p.rrp||0)})+'<div class="bs-savebar"><div><strong>Bundle components are linked to live catalogue records</strong><span>Review your changes, then save. Reset restores the last saved bundle.</span></div><button type="button" class="secondary" data-bs-reset>Reset changes</button><button type="button" class="secondary" data-bs-refresh>Refresh stock</button><button type="button" data-bs-save>Save bundle</button></div>'}
function wizardBuilder(form){var price=form&&form.querySelector('[name="rrp"]')?Number(form.querySelector('[name="rrp"]').value||0):0;return '<div class="product-step-heading"><span>06</span><div><h2>Bundle Builder</h2><p>Create the head product, then link components directly from the Product Hub catalogue.</p></div></div><div class="bs-wizard-type"><label>Product structure<select name="structure" data-bs-structure><option>Simple product</option><option>Variant</option><option selected>Bundle</option></select></label><div><strong>This product will be a virtual bundle</strong><p>It will not hold its own physical stock. Stock is allocated from the linked component SKUs.</p></div></div>'+builderShell({mode:'wizard',items:wizardDraft,price:price})+'<textarea name="bundleComponents" data-bs-hidden-components hidden></textarea><input name="bundleItemsJson" data-bs-hidden-json type="hidden">'}
function syncWizardHidden(root){var text=wizardDraft.map(function(r){var p=productById(r.productId);return(p?p.sku:r.productId)+' | '+Number(r.qty||1)}).join('\n');var ta=root.querySelector('[data-bs-hidden-components]'),json=root.querySelector('[data-bs-hidden-json]');if(ta)ta.value=text;if(json)json.value=JSON.stringify(wizardDraft)}
function mountProfileLegacy(){var old=document.querySelector('[data-product-field$="|bundleEnabled"]');if(!old)return;var id=(old.dataset.productField||'').split('|')[0],p=productById(id);if(!p)return;var container=old.closest('.product-tab-grid')||old.closest('.product-tab-card');if(container&&!container.querySelector('.bs-studio'))container.outerHTML=profileBuilder(p)}
function mountWizard(){var panel=document.querySelector('[data-product-step-panel="variants"]');if(!panel||panel.dataset.bsMounted==='1')return;var form=panel.closest('form');var structure=panel.querySelector('[name="structure"]');if(structure&&structure.value!=='Bundle')return;panel.dataset.bsMounted='1';panel.innerHTML=wizardBuilder(form);syncWizardHidden(panel)}
function scheduleMount(){if(renderQueued)return;renderQueued=true;requestAnimationFrame(function(){renderQueued=false;mountProfileLegacy();mountWizard()})}
function rootFrom(el){return el.closest('.bs-studio')}
function stateFrom(root){if(root.dataset.bsMode==='wizard')return wizardDraft;var p=productById(root.dataset.bsProductId);return p?profileDraft(p):[]}
function rerender(root){if(!root)return;if(root.dataset.bsMode==='wizard'){var panel=root.closest('[data-product-step-panel="variants"]');if(panel){panel.innerHTML=wizardBuilder(panel.closest('form'));syncWizardHidden(panel)}}else{var p=productById(root.dataset.bsProductId);var wrapper=root.parentElement;if(p&&wrapper){var savebar=document.querySelector('.bs-savebar');if(savebar)savebar.remove();root.outerHTML=profileBuilder(p)}}}
function positionResults(input,results){if(!input||!results)return;results.style.left='0';results.style.right='0';results.style.top='calc(100% + 8px)';results.style.width='auto';results.style.maxHeight=Math.max(220,Math.min(460,window.innerHeight-input.getBoundingClientRect().bottom-28))+'px'}
function closeResults(results){if(!results)return;results.classList.remove('open');results.style.left=results.style.right=results.style.top=results.style.width=results.style.maxHeight='';var card=results.closest('.bs-search-card');if(card)card.classList.remove('results-open')}
function updateSearch(input){var root=rootFrom(input),results=root.querySelector('[data-bs-results]'),items=stateFrom(root),matches=searchProducts(input.value,root.dataset.bsProductId,items.map(function(x){return x.productId}));var card=input.closest('.bs-search-card');if(card)card.classList.add('results-open');var catalogue=products();results.innerHTML=input.value.trim().length<2?'<div class="bs-search-message">Type at least 2 characters to search the Product Hub.</div>':matches.length?matches.map(resultRow).join(''):catalogue.length?'<div class="bs-search-message">No matching live catalogue products. Check the SKU or try part of the product name.</div>':'<div class="bs-search-message bs-search-error"><strong>Catalogue is still loading.</strong><span>Please wait a moment and type again. The Bundle Builder will reconnect automatically.</span></div>';positionResults(input,results);results.classList.add('open');results.setAttribute('aria-live','polite');results.dataset.catalogueCount=String(catalogue.length)}
function addItem(root,id){var items=stateFrom(root);if(items.some(function(x){return String(x.productId)===String(id)}))return;if(root.dataset.bsMode==='wizard'){wizardDraft=items.concat({productId:id,qty:1,displayOrder:items.length})}else{var p=productById(root.dataset.bsProductId);profileDrafts.set(String(p.id),items.concat({productId:id,qty:1,displayOrder:items.length}))}rerender(root)}
function removeItem(root,id){var items=stateFrom(root).filter(function(x){return String(x.productId)!==String(id)});if(root.dataset.bsMode==='wizard')wizardDraft=items;else{var p=productById(root.dataset.bsProductId);profileDrafts.set(String(p.id),items)}rerender(root)}
function saveProfile(root){var p=productById(root.dataset.bsProductId);if(!p)return;p.bundleItems=cloneItems(profileDraft(p));p.productType='Bundle Product';p.structure='Bundle';p.stockTracked=false;p.bundleEnabled='Yes';p.bundleAvailabilityRule='Lowest component availability';p.bundleComponents=linked(p).map(function(r){var x=productById(r.productId);return(x?x.sku:r.productId)+' | '+r.qty}).join('\n');p.updatedAt=new Date().toISOString();profileDrafts.set(String(p.id),cloneItems(p.bundleItems));if(typeof window.saveAppData==='function')window.saveAppData();if(typeof window.toast==='function')window.toast('Bundle saved with live catalogue links.');if(typeof window.render==='function')window.render()}

document.addEventListener('input',function(e){var pickerSearch=e.target.closest('[data-bs-picker-search]');if(pickerSearch){pickerState.query=pickerSearch.value;renderPicker();return}var search=e.target.closest('[data-bs-search]');if(search){updateSearch(search);return}var qty=e.target.closest('[data-bs-qty]');if(qty){var root=rootFrom(qty),items=stateFrom(root),row=items.find(function(x){return String(x.productId)===String(qty.dataset.bsQty)});if(row)row.qty=Math.max(1,Math.floor(Number(qty.value||1)));if(root.dataset.bsMode==='wizard')syncWizardHidden(root.closest('[data-product-step-panel="variants"]'));return}},true);
document.addEventListener('change',function(e){var pick=e.target.closest('[data-bs-picker-select]');if(pick){var id=String(pick.dataset.bsPickerSelect);if(pick.checked)pickerState.selected.add(id);else pickerState.selected.delete(id);renderPicker();return}var structure=e.target.closest('[name="structure"]');if(structure&&structure.value==='Bundle'){var panel=structure.closest('[data-product-step-panel="variants"]');if(panel){panel.dataset.bsMounted='';scheduleMount()}}},true);
document.addEventListener('click',function(e){var openPickerButton=e.target.closest('[data-bs-open-picker]');if(openPickerButton){openPicker(rootFrom(openPickerButton));return}var pickerClose=e.target.closest('[data-bs-picker-close]');if(pickerClose||e.target.matches('[data-bs-picker-modal]')){closePicker();return}var pickerClear=e.target.closest('[data-bs-picker-clear]');if(pickerClear){pickerState.selected.clear();renderPicker();return}var pickerAdd=e.target.closest('[data-bs-picker-add]');if(pickerAdd){addPickerSelection();return}var add=e.target.closest('[data-bs-add]');if(add){var root=rootFrom(add),results=add.closest('[data-bs-results]');addItem(root,add.dataset.bsAdd);closeResults(results);return}var remove=e.target.closest('[data-bs-remove]');if(remove){removeItem(rootFrom(remove),remove.dataset.bsRemove);return}var open=e.target.closest('[data-bs-open]');if(open&&typeof window.openProductProfile==='function'){window.openProductProfile(open.dataset.bsOpen);return}var save=e.target.closest('[data-bs-save]');if(save){saveProfile(document.querySelector('.bs-studio[data-bs-mode="profile"]'));return}var reset=e.target.closest('[data-bs-reset]');if(reset){var rr=document.querySelector('.bs-studio[data-bs-mode="profile"]'),pp=rr&&productById(rr.dataset.bsProductId);if(pp){profileDrafts.set(String(pp.id),cloneItems(linked(pp)));rerender(rr);if(typeof window.toast==='function')window.toast('Bundle changes reset.')}return}var refresh=e.target.closest('[data-bs-refresh]');if(refresh){rerender(document.querySelector('.bs-studio[data-bs-mode="profile"]'));return}},true);
document.addEventListener('keydown',function(e){if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){var input=document.querySelector('.bs-studio [data-bs-search]');if(input){e.preventDefault();input.focus()}}if(e.key==='Escape'){if(document.querySelector('[data-bs-picker-modal]'))closePicker();document.querySelectorAll('.bs-results.open').forEach(closeResults)}},true);
document.addEventListener('click',function(e){if(!e.target.closest('.bs-search-wrap'))document.querySelectorAll('.bs-results.open').forEach(closeResults)});
window.addEventListener('resize',function(){document.querySelectorAll('.bs-results.open').forEach(function(results){var input=results.closest('.bs-search-wrap').querySelector('[data-bs-search]');if(input)positionResults(input,results)})});
window.addEventListener('scroll',function(){document.querySelectorAll('.bs-results.open').forEach(function(results){var input=results.closest('.bs-search-wrap').querySelector('[data-bs-search]');if(input)positionResults(input,results)})},true);
document.addEventListener('submit',function(e){var form=e.target;if(!form||!form.querySelector('[data-product-step-panel="variants"]'))return;var structure=form.querySelector('[name="structure"]');if(!structure||structure.value!=='Bundle')return;var panel=form.querySelector('[data-product-step-panel="variants"]');syncWizardHidden(panel);var sku=(form.querySelector('[name="sku"]')||{}).value;setTimeout(function(){var p=products().find(function(x){return x&&!x.deleted&&String(x.sku||'').toLowerCase()===String(sku||'').toLowerCase()});if(!p)return;p.bundleItems=JSON.parse(JSON.stringify(wizardDraft));p.productType='Bundle Product';p.structure='Bundle';p.stockTracked=false;p.bundleEnabled='Yes';p.bundleAvailabilityRule='Lowest component availability';p.bundleComponents=wizardDraft.map(function(r){var x=productById(r.productId);return(x?x.sku:r.productId)+' | '+r.qty}).join('\n');if(typeof window.saveAppData==='function')window.saveAppData();wizardDraft=[]},0)},true);

var oldTab=window.productProfileTabContent;
if(typeof oldTab==='function')window.productProfileTabContent=function(p,s){if(window.productTab==='bundle'&&isBundle(p))return profileBuilder(p);return oldTab(p,s)};
new MutationObserver(scheduleMount).observe(document.documentElement,{childList:true,subtree:true});
scheduleMount();
window.PoolShedBundleStudio={version:VERSION,search:searchProducts,calculate:calc};
})();
